create or replace function public.upsert_housekeeping_completion(p_hotel_id text,p_camera text,p_room_type text,p_section text,p_floor integer,p_housekeeper_name text) returns public.housekeeping_completions language plpgsql security definer set search_path=public as $$ declare v_uid uuid:=auth.uid(); v_row public.housekeeping_completions; begin if v_uid is null then raise exception 'Non autenticato' using errcode='28000'; end if; if not public.has_hotel_role(p_hotel_id,array['admin','Direzione','Reception','Governante','Capo Governante']) then raise exception 'Non autorizzato' using errcode='42501'; end if; insert into public.housekeeping_completions(hotel_id,work_date,camera,room_type,section,floor,housekeeper_user_id,housekeeper_name_snapshot,completed_at,updated_at) values(p_hotel_id,current_date,p_camera,coalesce(nullif(trim(p_room_type),''),'Standard'),nullif(trim(p_section),''),p_floor,v_uid,coalesce(nullif(trim(p_housekeeper_name),''),'Governante'),now(),now()) on conflict(hotel_id,work_date,camera) do update set room_type=excluded.room_type,section=excluded.section,floor=excluded.floor,housekeeper_user_id=excluded.housekeeper_user_id,housekeeper_name_snapshot=excluded.housekeeper_name_snapshot,completed_at=excluded.completed_at,updated_at=now() returning * into v_row; return v_row; end; $$;
create or replace function public.clear_housekeeping_completion(p_hotel_id text,p_camera text) returns void language plpgsql security definer set search_path=public as $$ begin if auth.uid() is null then raise exception 'Non autenticato' using errcode='28000'; end if; if not public.has_hotel_role(p_hotel_id,array['admin','Direzione','Reception','Governante','Capo Governante']) then raise exception 'Non autorizzato' using errcode='42501'; end if; delete from public.housekeeping_completions where hotel_id=p_hotel_id and work_date=current_date and camera=p_camera; end; $$;
revoke execute on function public.upsert_housekeeping_completion(text,text,text,text,integer,text) from public,anon; revoke execute on function public.clear_housekeeping_completion(text,text) from public,anon; grant execute on function public.upsert_housekeeping_completion(text,text,text,text,integer,text) to authenticated,service_role; grant execute on function public.clear_housekeeping_completion(text,text) to authenticated,service_role;
